package com.quicknotes.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public class ReminderWidget extends AppWidgetProvider {
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("widgets",0);}
 static JSONObject read(Context c){synchronized(MainActivity.STORE_LOCK){try(InputStream in=new FileInputStream(new File(c.getFilesDir(),"data.json"))){return MainActivity.validate(new JSONObject(new String(MainActivity.bytes(in,MainActivity.MAX_BUNDLE),"UTF-8")));}catch(Exception e){return new JSONObject();}}}
 static List<JSONObject> rows(Context c,String view){JSONObject d=read(c);JSONArray a=d.optJSONArray("items"),ls=d.optJSONArray("lists");Set<String> active=new HashSet<>();if(ls!=null)for(int n=0;n<ls.length();n++){JSONObject l=ls.optJSONObject(n);if(l!=null&&!l.optBoolean("deleted"))active.add(l.optString("id"));}List<JSONObject> out=new ArrayList<>();Calendar tomorrow=Calendar.getInstance();tomorrow.set(Calendar.HOUR_OF_DAY,0);tomorrow.set(Calendar.MINUTE,0);tomorrow.set(Calendar.SECOND,0);tomorrow.set(Calendar.MILLISECOND,0);tomorrow.add(Calendar.DATE,1);if(a!=null)for(int n=0;n<a.length();n++){JSONObject i=a.optJSONObject(n);if(i==null||i.optBoolean("deleted")||(i.optBoolean("done")&&!view.equals("completed")||!i.optBoolean("done")&&view.equals("completed"))||!active.contains(i.optString("list")))continue;long due=i.optLong("due");if(view.equals("all")||view.equals("completed")||view.equals("urgent")&&i.optBoolean("urgent")||view.equals(i.optString("list"))||view.equals("today")&&due>0&&due<tomorrow.getTimeInMillis()||view.equals("scheduled")&&due>0||view.equals("flagged")&&i.optBoolean("flag"))out.add(i);}Collections.sort(out,(a1,b)->{long x=a1.optLong("due"),y=b.optLong("due");int n=Long.compare(x==0?Long.MAX_VALUE:x,y==0?Long.MAX_VALUE:y);return n!=0?n:a1.optString("title").compareToIgnoreCase(b.optString("title"));});return out;}
 static boolean canComplete(Context c,int id){return id>=0&&prefs(c).getBoolean(id+"complete",true);}
 static boolean appDark(Context c){String t=c.getSharedPreferences("MainActivity",0).getString("theme","system");return t.equals("dark")||t.equals("system")&&(c.getResources().getConfiguration().uiMode&48)==32;}
 static boolean dark(Context c,int id){String t=prefs(c).getString(id+"theme","app");return t.equals("app")?appDark(c):t.equals("dark")||t.equals("system")&&(c.getResources().getConfiguration().uiMode&48)==32;}
 static int background(Context c,int id){String mode=prefs(c).getString(id+"theme","app");int fallback=dark(c,id)?0xff202124:0xfff2f2f7;if(mode.equals("custom"))return Colors.parse(prefs(c).getString(id+"background",""),fallback);if(mode.equals("list")){String list=prefs(c).getString(id+"list","all");JSONArray lists=read(c).optJSONArray("lists");if(lists!=null)for(int n=0;n<lists.length();n++){JSONObject l=lists.optJSONObject(n);if(l!=null&&!l.optBoolean("deleted")&&list.equals(l.optString("id")))return Colors.parse(l.optString("backgroundColor"),fallback);}}if(mode.equals("app"))return Colors.parse(c.getSharedPreferences("MainActivity",0).getString("appBackground",""),fallback);return fallback;}
 static String adapterIdentity(Context c,int id){return "quicknotes-widget://"+id+"/"+Uri.encode(prefs(c).getString(id+"list","all"))+"?theme="+prefs(c).getString(id+"theme","app")+"&background="+background(c,id)+"&complete="+canComplete(c,id);}
 static RemoteViews build(Context c,int id){String view=prefs(c).getString(id+"list","all");WidgetChoices.Choice choice=WidgetChoices.find(c,view);String title=WidgetChoices.symbol(choice.icon)+"  "+choice.title;boolean dark=dark(c,id);RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.reminder_widget);r.setInt(R.id.widget_root,"setBackgroundColor",background(c,id));r.setTextViewText(R.id.widget_title,title);r.setTextColor(R.id.widget_title,Colors.text(background(c,id)));r.setTextViewText(R.id.widget_empty,"No reminders");r.setTextColor(R.id.widget_empty,Colors.text(background(c,id)));Intent service=new Intent(c,WidgetService.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);service.setData(Uri.parse(adapterIdentity(c,id)));r.setRemoteAdapter(R.id.widget_list,service);r.setEmptyView(R.id.widget_list,R.id.widget_empty);
 r.setTextColor(R.id.widget_add,Colors.text(background(c,id)));r.setTextColor(R.id.widget_settings,Colors.text(background(c,id)));Intent open=new Intent(c,MainActivity.class).setAction("com.quicknotes.app.WIDGET").setData(Uri.parse("quicknotes://widget/"+id)).putExtra("widgetList",view);r.setPendingIntentTemplate(R.id.widget_list,PendingIntent.getBroadcast(c,id,new Intent(c,Reminders.class).setAction("WIDGET_ROW").setData(Uri.parse("quicknotes://widget-action/"+id)).putExtra("widgetList",view).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE));r.setOnClickPendingIntent(R.id.widget_title,PendingIntent.getActivity(c,id+100000,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));r.setOnClickPendingIntent(R.id.widget_add,PendingIntent.getActivity(c,id+200000,new Intent(open).setAction("com.quicknotes.app.NEW_REMINDER"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));r.setOnClickPendingIntent(R.id.widget_settings,PendingIntent.getActivity(c,id+300000,new Intent(c,WidgetConfigActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).setData(Uri.parse("quicknotes://configure/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));return r;}
 static void update(Context c,int id){AppWidgetManager m=AppWidgetManager.getInstance(c);m.updateAppWidget(id,build(c,id));m.notifyAppWidgetViewDataChanged(id,R.id.widget_list);}
 static void refresh(Context c){for(int id:AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,ReminderWidget.class)))update(c,id);}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,id);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle b){update(c,id);}
 @Override public void onDeleted(Context c,int[] ids){for(int id:ids)prefs(c).edit().remove(id+"list").remove(id+"theme").remove(id+"complete").remove(id+"background").apply();}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(Intent.ACTION_TIME_CHANGED.equals(i.getAction())||Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction())||Intent.ACTION_DATE_CHANGED.equals(i.getAction()))refresh(c);}
}
